import{_ as t,o as a,c as o,ag as d}from"./chunks/framework.B7PviQjB.js";const p=JSON.parse('{"title":"Developers","description":"Script Wafflebase from the terminal, call it over HTTP, let Claude Code work in your workspace, or run your own server.","frontmatter":{"title":"Developers","description":"Script Wafflebase from the terminal, call it over HTTP, let Claude Code work in your workspace, or run your own server.","type":"overview"},"headers":[],"relativePath":"developers/index.md","filePath":"developers/index.md"}'),r={name:"developers/index.md"};function s(l,e,n,i,h,c){return a(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="developers" tabindex="-1">Developers <a class="header-anchor" href="#developers" aria-label="Permalink to &quot;Developers&quot;">​</a></h1><p>Wafflebase gives developers four ways in: a command-line tool, a REST API, a Claude Code plugin, and a server you can host yourself.</p><p>Use it to:</p><ul><li>Script your documents: load CSV data into a sheet, export a doc to PDF, or import a PowerPoint deck.</li><li>Connect another service over HTTP with a workspace API key.</li><li>Let Claude Code find, read, and edit documents for you, asking before every change.</li><li>Run Wafflebase on your own infrastructure.</li></ul><h2 id="get-started" tabindex="-1">Get started <a class="header-anchor" href="#get-started" aria-label="Permalink to &quot;Get started&quot;">​</a></h2><ol><li>Install the CLI and sign in: <code>npm install -g @wafflebase/cli</code>, then <code>wafflebase login</code>. See <a href="/docs/developers/cli/">Install and sign in</a>.</li><li>List your documents with <code>wafflebase docs list --format table</code>, then read one with <code>wafflebase docs content &lt;doc-id&gt; --format md</code>. See <a href="/docs/developers/cli/documents.html">Documents and notes</a>.</li><li>Automate it: create an API key and run the same commands from a script or CI job. See <a href="/docs/developers/cli/automation.html">Automation and agents</a>.</li></ol><h2 id="use-the-command-line" tabindex="-1">Use the command line <a class="header-anchor" href="#use-the-command-line" aria-label="Permalink to &quot;Use the command line&quot;">​</a></h2><table tabindex="0"><thead><tr><th>To do this</th><th>See</th></tr></thead><tbody><tr><td>Install the CLI, sign in, and pick a workspace</td><td><a href="/docs/developers/cli/">Install and sign in</a></td></tr><tr><td>Create, copy, move, read, import, and export docs and notes; manage folders, comments, and templates</td><td><a href="/docs/developers/cli/documents.html">Documents and notes</a></td></tr><tr><td>Read and write cells, import CSV, and format tabs</td><td><a href="/docs/developers/cli/sheets.html">Sheets</a></td></tr><tr><td>Build and check decks, and add stickies and sections to a board</td><td><a href="/docs/developers/cli/slides-and-board.html">Slides and boards</a></td></tr><tr><td>Store any file as a document and upload images</td><td><a href="/docs/developers/cli/files-and-images.html">Files and images</a></td></tr><tr><td>Run the CLI in CI or from an agent, and handle its errors</td><td><a href="/docs/developers/cli/automation.html">Automation and agents</a></td></tr></tbody></table><h2 id="work-with-claude-code" tabindex="-1">Work with Claude Code <a class="header-anchor" href="#work-with-claude-code" aria-label="Permalink to &quot;Work with Claude Code&quot;">​</a></h2><table tabindex="0"><thead><tr><th>To do this</th><th>See</th></tr></thead><tbody><tr><td>Install the plugin, find and publish documents, and control what asks for confirmation</td><td><a href="/docs/developers/claude-code-plugin.html">Claude Code plugin</a></td></tr></tbody></table><h2 id="call-the-rest-api" tabindex="-1">Call the REST API <a class="header-anchor" href="#call-the-rest-api" aria-label="Permalink to &quot;Call the REST API&quot;">​</a></h2><table tabindex="0"><thead><tr><th>To do this</th><th>See</th></tr></thead><tbody><tr><td>Learn the base URL, authentication, and errors</td><td><a href="/docs/developers/api/">REST API overview</a></td></tr><tr><td>Make your first calls with an API key</td><td><a href="/docs/developers/api/quickstart.html">Quickstart</a></td></tr><tr><td>Manage documents and folders</td><td><a href="/docs/developers/api/documents-and-folders.html">Documents and folders</a></td></tr><tr><td>Read and write sheets</td><td><a href="/docs/developers/api/sheets.html">Sheets</a></td></tr><tr><td>Read and replace document content</td><td><a href="/docs/developers/api/content.html">Document content</a></td></tr><tr><td>Add and arrange board elements</td><td><a href="/docs/developers/api/board.html">Boards</a></td></tr><tr><td>Get a signed request when something changes in a workspace</td><td><a href="/docs/developers/webhooks.html">Webhooks</a></td></tr></tbody></table><h2 id="host-your-own-server" tabindex="-1">Host your own server <a class="header-anchor" href="#host-your-own-server" aria-label="Permalink to &quot;Host your own server&quot;">​</a></h2><table tabindex="0"><thead><tr><th>To do this</th><th>See</th></tr></thead><tbody><tr><td>See what you run and what you need</td><td><a href="/docs/developers/self-hosting/">Self-hosting overview</a></td></tr><tr><td>Run the full stack on your computer</td><td><a href="/docs/developers/self-hosting/local-development.html">Local development</a></td></tr><tr><td>Look up environment variables</td><td><a href="/docs/developers/self-hosting/configuration.html">Configuration</a></td></tr><tr><td>Set up GitHub, GitHub Enterprise, or Google sign-in</td><td><a href="/docs/developers/self-hosting/sign-in.html">Sign-in providers</a></td></tr><tr><td>Deploy to a real domain</td><td><a href="/docs/developers/self-hosting/deploy.html">Deploy to production</a></td></tr><tr><td>Turn on analytics, lakehouse tables, error tracking, webhooks, or the public template gallery</td><td><a href="/docs/developers/self-hosting/optional-features.html">Optional features</a></td></tr><tr><td>Fix a deployment that misbehaves</td><td><a href="/docs/developers/self-hosting/troubleshooting.html">Troubleshooting</a></td></tr></tbody></table><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="/docs/developers/cli/">Install and sign in</a> to start using the CLI.</li><li><a href="/docs/developers/claude-code-plugin.html">Claude Code plugin</a> to work on documents by asking Claude.</li><li><a href="/docs/developers/api/quickstart.html">REST API quickstart</a> to call Wafflebase from your own code.</li><li><a href="/docs/developers/self-hosting/local-development.html">Local development</a> to run Wafflebase on your computer.</li></ul>',16)])])}const m=t(r,[["render",s]]);export{p as __pageData,m as default};
